INSERT INTO translations (page_name, text_key, english, spanish, portuguese, french, german, italian, polish, czech, russian, turkish, croatian, norwegian) VALUES
('players', 'scout', 'SCOUT', 'EXPLORAR', 'EXPLORAR', 'DÉPISTER', 'SCOUTEN', 'ESPLORARE', 'SKAUTOWAĆ', 'SKAUTOVAT', 'СКАУТИНГ', 'KEŞFET', 'SKAUTIRATI', 'SPEIDE'),
('players', 'scout_subtitle', 'Discovery & Identification', 'Descubrimiento e Identificación', 'Descoberta e Identificação', 'Découverte et Identification', 'Entdeckung und Identifikation', 'Scoperta e Identificazione', 'Odkrywanie i Identyfikacja', 'Objevování a Identifikace', 'Обнаружение и Идентификация', 'Keşif ve Tanımlama', 'Otkrivanje i Identifikacija', 'Oppdagelse og Identifisering'),
('players', 'scout_desc', 'Our extensive global scouting network identifies exceptional talent across every level of the game. From grassroots academies to professional leagues, we find players with the technical ability, mentality, and ambition to succeed at the highest level.', 'Nuestra extensa red global de scouts identifica talento excepcional en todos los niveles del juego. Desde academias de base hasta ligas profesionales, encontramos jugadores con la capacidad técnica, mentalidad y ambición para triunfar al más alto nivel.', 'A nossa extensa rede global de scouting identifica talentos excepcionais em todos os níveis do jogo. Desde academias de base até ligas profissionais, encontramos jogadores com capacidade técnica, mentalidade e ambição para ter sucesso ao mais alto nível.', 'Notre vaste réseau mondial de recrutement identifie les talents exceptionnels à tous les niveaux du jeu. Des académies de base aux ligues professionnelles, nous trouvons des joueurs dotés de capacités techniques, de mentalité et d''ambition pour réussir au plus haut niveau.', 'Unser umfangreiches globales Scouting-Netzwerk identifiziert außergewöhnliche Talente auf jedem Niveau des Spiels. Von Nachwuchsakademien bis zu Profiligen finden wir Spieler mit technischer Fähigkeit, Mentalität und Ehrgeiz, um auf höchstem Niveau erfolgreich zu sein.', 'La nostra vasta rete di scouting globale identifica talenti eccezionali a ogni livello del gioco. Dalle accademie giovanili ai campionati professionistici, troviamo giocatori con capacità tecniche, mentalità e ambizione per avere successo ai massimi livelli.', 'Nasza rozległa globalna sieć skautów identyfikuje wyjątkowe talenty na każdym poziomie gry. Od akademii młodzieżowych po ligi zawodowe, znajdujemy piłkarzy z umiejętnościami technicznymi, mentalnością i ambicją, by odnieść sukces na najwyższym poziomie.', 'Naše rozsáhlá globální skautingová síť identifikuje výjimečné talenty na každé úrovni hry. Od mládežnických akademií po profesionální ligy nacházíme hráče s technickými schopnostmi, mentalitou a ambicemi uspět na nejvyšší úrovni.', 'Наша обширная глобальная скаутинговая сеть выявляет исключительные таланты на всех уровнях игры. От молодёжных академий до профессиональных лиг мы находим игроков с техническими навыками, менталитетом и амбициями для успеха на высшем уровне.', 'Kapsamlı küresel keşif ağımız, oyunun her seviyesindeki olağanüstü yetenekleri belirler. Altyapı akademilerinden profesyonel liglere kadar, en üst düzeyde başarılı olmak için teknik yeteneğe, mentaliteye ve hırsa sahip oyuncuları buluyoruz.', 'Naša opsežna globalna mreža skauta identificira izvanredne talente na svim razinama igre. Od omladinskih akademija do profesionalnih liga, pronalazimo igrače s tehničkim sposobnostima, mentalitetom i ambicijom za uspjeh na najvišoj razini.', 'Vårt omfattende globale speidernettverk identifiserer eksepsjonelt talent på alle nivåer av spillet. Fra gressrotsakademier til profesjonelle ligaer finner vi spillere med teknisk evne, mentalitet og ambisjoner for å lykkes på høyeste nivå.'),
('players', 'scout_details', '• Network of 50+ scouts across 20 countries\n• Data-driven player analysis and profiling\n• Video assessment and live match evaluation\n• Character and mentality assessment', '• Red de más de 50 scouts en 20 países\n• Análisis y perfilado de jugadores basado en datos\n• Evaluación por vídeo y evaluación en vivo\n• Evaluación de carácter y mentalidad', '• Rede de mais de 50 olheiros em 20 países\n• Análise e perfil de jogadores baseados em dados\n• Avaliação por vídeo e avaliação ao vivo\n• Avaliação de carácter e mentalidade', '• Réseau de plus de 50 recruteurs dans 20 pays\n• Analyse et profilage de joueurs basés sur les données\n• Évaluation vidéo et évaluation en direct\n• Évaluation du caractère et de la mentalité', '• Netzwerk von über 50 Scouts in 20 Ländern\n• Datengesteuerte Spieleranalyse und Profilerstellung\n• Videoauswertung und Live-Spielbewertung\n• Charakter- und Mentalitätsbewertung', '• Rete di oltre 50 scout in 20 paesi\n• Analisi e profilazione dei giocatori basata sui dati\n• Valutazione video e valutazione delle partite dal vivo\n• Valutazione del carattere e della mentalità', '• Sieć ponad 50 skautów w 20 krajach\n• Analiza i profilowanie zawodników oparte na danych\n• Ocena wideo i ocena meczów na żywo\n• Ocena charakteru i mentalności', '• Síť více než 50 skautů ve 20 zemích\n• Datově řízená analýza a profilování hráčů\n• Video hodnocení a hodnocení zápasů naživo\n• Hodnocení charakteru a mentality', '• Сеть из более чем 50 скаутов в 20 странах\n• Анализ и профилирование игроков на основе данных\n• Видеоанализ и оценка матчей вживую\n• Оценка характера и менталитета', '• 20 ülkede 50''den fazla keşifçiden oluşan ağ\n• Veri odaklı oyuncu analizi ve profilleme\n• Video değerlendirmesi ve canlı maç değerlendirmesi\n• Karakter ve mentalite değerlendirmesi', '• Mreža od više od 50 skauta u 20 zemalja\n• Analiza i profiliranje igrača temeljena na podacima\n• Video procjena i procjena utakmica uživo\n• Procjena karaktera i mentaliteta', '• Nettverk med over 50 speidere i 20 land\n• Datadrevet spilleranalyse og profilering\n• Videovurdering og live kampvurdering\n• Karakter- og mentalitetsvurdering'),
('players', 'represent', 'REPRESENT', 'REPRESENTAR', 'REPRESENTAR', 'REPRÉSENTER', 'VERTRETEN', 'RAPPRESENTARE', 'REPREZENTOWAĆ', 'ZASTUPOVAT', 'ПРЕДСТАВЛЯТЬ', 'TEMSİL ET', 'ZASTUPATI', 'REPRESENTERE'),
('players', 'represent_subtitle', 'Partnership & Protection', 'Asociación y Protección', 'Parceria e Proteção', 'Partenariat et Protection', 'Partnerschaft und Schutz', 'Partnership e Protezione', 'Partnerstwo i Ochrona', 'Partnerství a Ochrana', 'Партнёрство и Защита', 'Ortaklık ve Koruma', 'Partnerstvo i Zaštita', 'Partnerskap og Beskyttelse'),
('players', 'represent_desc', 'When we identify the right fit, we build a genuine partnership. Our experienced intermediaries negotiate contracts that protect your interests and maximise your earning potential, ensuring you''re valued fairly at every stage of your career.', 'Cuando identificamos el ajuste correcto, construimos una asociación genuina. Nuestros intermediarios experimentados negocian contratos que protegen tus intereses y maximizan tu potencial de ganancias.', 'Quando identificamos o ajuste certo, construímos uma parceria genuína. Os nossos intermediários experientes negoceiam contratos que protegem os seus interesses e maximizam o seu potencial de ganhos.', 'Lorsque nous identifions le bon profil, nous construisons un véritable partenariat. Nos intermédiaires expérimentés négocient des contrats qui protègent vos intérêts et maximisent votre potentiel de revenus.', 'Wenn wir die richtige Passung finden, bauen wir eine echte Partnerschaft auf. Unsere erfahrenen Vermittler verhandeln Verträge, die Ihre Interessen schützen und Ihr Einkommenspotenzial maximieren.', 'Quando identifichiamo la giusta compatibilità, costruiamo una partnership genuina. I nostri intermediari esperti negoziano contratti che proteggono i tuoi interessi e massimizzano il tuo potenziale di guadagno.', 'Kiedy znajdziemy odpowiednie dopasowanie, budujemy prawdziwe partnerstwo. Nasi doświadczeni pośrednicy negocjują kontrakty chroniące twoje interesy i maksymalizujące twój potencjał zarobkowy.', 'Když najdeme správnou shodu, budujeme skutečné partnerství. Naši zkušení zprostředkovatelé vyjednávají smlouvy, které chrání vaše zájmy a maximalizují váš výdělkový potenciál.', 'Когда мы определяем правильное соответствие, мы строим настоящее партнёрство. Наши опытные посредники ведут переговоры по контрактам, которые защищают ваши интересы и максимизируют ваш заработок.', 'Doğru uyumu belirlediğimizde gerçek bir ortaklık kuruyoruz. Deneyimli aracılarımız çıkarlarınızı koruyan ve kazanç potansiyelinizi en üst düzeye çıkaran sözleşmeler müzakere eder.', 'Kada identificiramo pravi spoj, gradimo istinsko partnerstvo. Naši iskusni posrednici pregovaraju ugovore koji štite vaše interese i maksimiziraju vaš potencijal zarade.', 'Når vi identifiserer riktig match, bygger vi et genuint partnerskap. Våre erfarne mellommenn forhandler kontrakter som beskytter dine interesser og maksimerer inntjeningspotensialet ditt.'),
('players', 'represent_details', '• Expert contract negotiation and review\n• Legal protection and compliance guidance\n• Transfer market positioning\n• Career pathway planning', '• Negociación y revisión experta de contratos\n• Protección legal y orientación de cumplimiento\n• Posicionamiento en el mercado de fichajes\n• Planificación de la trayectoria profesional', '• Negociação e revisão especializada de contratos\n• Proteção legal e orientação de conformidade\n• Posicionamento no mercado de transferências\n• Planeamento de percurso profissional', '• Négociation et révision experte de contrats\n• Protection juridique et conseils de conformité\n• Positionnement sur le marché des transferts\n• Planification du parcours de carrière', '• Experthafte Vertragsverhandlung und -prüfung\n• Rechtsschutz und Compliance-Beratung\n• Transfermarkt-Positionierung\n• Karrierepfad-Planung', '• Negoziazione e revisione esperta dei contratti\n• Protezione legale e guida alla conformità\n• Posizionamento sul mercato dei trasferimenti\n• Pianificazione del percorso di carriera', '• Eksperckie negocjacje i przegląd kontraktów\n• Ochrona prawna i doradztwo w zakresie zgodności\n• Pozycjonowanie na rynku transferowym\n• Planowanie ścieżki kariery', '• Odborné vyjednávání a kontrola smluv\n• Právní ochrana a poradenství v oblasti compliance\n• Pozicování na přestupovém trhu\n• Plánování kariérní cesty', '• Экспертные переговоры и проверка контрактов\n• Правовая защита и консультации по соблюдению норм\n• Позиционирование на трансферном рынке\n• Планирование карьерного пути', '• Uzman sözleşme müzakeresi ve incelemesi\n• Hukuki koruma ve uyum rehberliği\n• Transfer pazarı konumlandırması\n• Kariyer yolu planlaması', '• Stručno pregovaranje i pregled ugovora\n• Pravna zaštita i savjetovanje o usklađenosti\n• Pozicioniranje na transfernom tržištu\n• Planiranje karijerne putanje', '• Ekspertforhandling og gjennomgang av kontrakter\n• Juridisk beskyttelse og samsvarsveiledning\n• Posisjonering i overgangsmarkedet\n• Karriereveiplanlegging'),
('players', 'develop_subtitle', 'Growth & Excellence', 'Crecimiento y Excelencia', 'Crescimento e Excelência', 'Croissance et Excellence', 'Wachstum und Exzellenz', 'Crescita ed Eccellenza', 'Rozwój i Doskonałość', 'Růst a Excelence', 'Рост и Совершенство', 'Büyüme ve Mükemmellik', 'Rast i Izvrsnost', 'Vekst og Fremragenhet'),
('players', 'develop_desc', 'Development never stops. Our specialist coaching team creates personalised programmes to enhance every aspect of your game: physical conditioning, technical refinement, tactical understanding, and mental resilience. We push boundaries to unlock your full potential.', 'El desarrollo nunca se detiene. Nuestro equipo de entrenadores especialistas crea programas personalizados para mejorar cada aspecto de tu juego: acondicionamiento físico, refinamiento técnico, comprensión táctica y resiliencia mental.', 'O desenvolvimento nunca para. A nossa equipa de treinadores especialistas cria programas personalizados para melhorar todos os aspetos do seu jogo: condicionamento físico, refinamento técnico, compreensão tática e resiliência mental.', 'Le développement ne s''arrête jamais. Notre équipe d''entraîneurs spécialisés crée des programmes personnalisés pour améliorer chaque aspect de votre jeu : condition physique, raffinement technique, compréhension tactique et résilience mentale.', 'Entwicklung hört nie auf. Unser spezialisiertes Trainerteam erstellt personalisierte Programme zur Verbesserung jedes Aspekts Ihres Spiels: körperliche Kondition, technische Verfeinerung, taktisches Verständnis und mentale Belastbarkeit.', 'Lo sviluppo non si ferma mai. Il nostro team di allenatori specializzati crea programmi personalizzati per migliorare ogni aspetto del tuo gioco: preparazione fisica, raffinamento tecnico, comprensione tattica e resilienza mentale.', 'Rozwój nigdy się nie kończy. Nasz specjalistyczny zespół trenerski tworzy spersonalizowane programy doskonalące każdy aspekt gry: kondycję fizyczną, doskonalenie techniczne, zrozumienie taktyczne i odporność psychiczną.', 'Vývoj se nikdy nezastaví. Náš tým specializovaných trenérů vytváří personalizované programy pro zlepšení každého aspektu vaší hry: fyzickou kondici, technické zdokonalení, taktické porozumění a mentální odolnost.', 'Развитие никогда не прекращается. Наша команда специализированных тренеров создаёт индивидуальные программы для улучшения каждого аспекта вашей игры: физическая подготовка, техническое совершенствование, тактическое понимание и психическая устойчивость.', 'Gelişim asla durmaz. Uzman antrenör ekibimiz oyununuzun her yönünü geliştirmek için kişiselleştirilmiş programlar oluşturur: fiziksel kondisyon, teknik iyileştirme, taktik anlayış ve zihinsel dayanıklılık.', 'Razvoj nikad ne prestaje. Naš specijalizirani trenerski tim kreira personalizirane programe za poboljšanje svakog aspekta vaše igre: fizičku kondiciju, tehničko usavršavanje, taktičko razumijevanje i mentalnu otpornost.', 'Utvikling stopper aldri. Vårt spesialiserte trenerteam lager personaliserte programmer for å forbedre alle aspekter av spillet ditt: fysisk kondisjon, teknisk finpussing, taktisk forståelse og mental motstandsdyktighet.'),
('players', 'develop_details', '• Bespoke physical training programmes\n• Technical and tactical coaching\n• Sports psychology and mental performance\n• Nutrition and recovery optimisation', '• Programas de entrenamiento físico a medida\n• Entrenamiento técnico y táctico\n• Psicología deportiva y rendimiento mental\n• Nutrición y optimización de la recuperación', '• Programas de treino físico personalizados\n• Treino técnico e tático\n• Psicologia desportiva e desempenho mental\n• Nutrição e otimização da recuperação', '• Programmes d''entraînement physique sur mesure\n• Coaching technique et tactique\n• Psychologie du sport et performance mentale\n• Nutrition et optimisation de la récupération', '• Maßgeschneiderte physische Trainingsprogramme\n• Technisches und taktisches Coaching\n• Sportpsychologie und mentale Leistung\n• Ernährung und Regenerationsoptimierung', '• Programmi di allenamento fisico su misura\n• Coaching tecnico e tattico\n• Psicologia sportiva e prestazione mentale\n• Nutrizione e ottimizzazione del recupero', '• Spersonalizowane programy treningowe\n• Trening techniczny i taktyczny\n• Psychologia sportu i wydajność mentalna\n• Żywienie i optymalizacja regeneracji', '• Fyzické tréninkové programy na míru\n• Technický a taktický koučink\n• Sportovní psychologie a mentální výkon\n• Výživa a optimalizace regenerace', '• Индивидуальные программы физической подготовки\n• Техническая и тактическая тренировка\n• Спортивная психология и ментальная подготовка\n• Питание и оптимизация восстановления', '• Kişiye özel fiziksel antrenman programları\n• Teknik ve taktik koçluk\n• Spor psikolojisi ve zihinsel performans\n• Beslenme ve toparlanma optimizasyonu', '• Prilagođeni programi fizičkog treninga\n• Tehnički i taktički coaching\n• Sportska psihologija i mentalni performans\n• Prehrana i optimizacija oporavka', '• Skreddersydde fysiske treningsprogrammer\n• Teknisk og taktisk coaching\n• Idrettspsykologi og mental prestasjon\n• Ernæring og restitusjonoptimalisering'),
('players', 'perform_subtitle', 'Consistency & Impact', 'Consistencia e Impacto', 'Consistência e Impacto', 'Constance et Impact', 'Konstanz und Wirkung', 'Costanza e Impatto', 'Konsekwencja i Wpływ', 'Konzistence a Dopad', 'Постоянство и Влияние', 'Tutarlılık ve Etki', 'Dosljednost i Utjecaj', 'Konsistens og Innvirkning'),
('players', 'perform_desc', 'Preparation meets opportunity. Through detailed opposition analysis, psychological coaching, and strategic preparation, we ensure you''re ready to deliver when it matters most. Consistent high performance opens doors to the biggest stages in football.', 'La preparación se encuentra con la oportunidad. A través del análisis detallado del rival, coaching psicológico y preparación estratégica, nos aseguramos de que estés listo para rendir cuando más importa.', 'A preparação encontra a oportunidade. Através de análise detalhada da oposição, coaching psicológico e preparação estratégica, garantimos que está pronto para entregar quando mais importa.', 'La préparation rencontre l''opportunité. Grâce à une analyse détaillée de l''adversaire, un coaching psychologique et une préparation stratégique, nous nous assurons que vous êtes prêt à performer quand cela compte le plus.', 'Vorbereitung trifft auf Gelegenheit. Durch detaillierte Gegneranalyse, psychologisches Coaching und strategische Vorbereitung stellen wir sicher, dass Sie bereit sind zu liefern, wenn es am meisten zählt.', 'La preparazione incontra l''opportunità. Attraverso un''analisi dettagliata dell''avversario, coaching psicologico e preparazione strategica, ci assicuriamo che tu sia pronto a dare il meglio quando conta di più.', 'Przygotowanie spotyka się z szansą. Dzięki szczegółowej analizie rywala, coachingowi psychologicznemu i strategicznemu przygotowaniu zapewniamy, że jesteś gotowy dostarczać wyniki, gdy to się najbardziej liczy.', 'Příprava se setkává s příležitostí. Díky detailní analýze soupeře, psychologickému koučinku a strategické přípravě zajistíme, že jste připraveni podávat výkony, když na tom nejvíce záleží.', 'Подготовка встречается с возможностью. Благодаря детальному анализу соперника, психологическому коучингу и стратегической подготовке мы обеспечиваем вашу готовность показывать результат, когда это важнее всего.', 'Hazırlık fırsatla buluşur. Detaylı rakip analizi, psikolojik koçluk ve stratejik hazırlık yoluyla en önemli anlarda performans göstermeye hazır olmanızı sağlıyoruz.', 'Priprema susreće priliku. Kroz detaljnu analizu protivnika, psihološki coaching i stratešku pripremu osiguravamo da ste spremni isporučiti kada je to najvažnije.', 'Forberedelse møter mulighet. Gjennom detaljert motstanderanalyse, psykologisk coaching og strategisk forberedelse sørger vi for at du er klar til å levere når det betyr mest.'),
('players', 'perform_details', '• Individual match preparation and analysis\n• Opposition scouting and tactical briefings\n• In-season performance monitoring\n• Post-match review and feedback', '• Preparación y análisis individual de partidos\n• Scouting del rival y briefings tácticos\n• Monitoreo de rendimiento durante la temporada\n• Revisión y feedback post-partido', '• Preparação e análise individual de jogos\n• Scouting da oposição e briefings táticos\n• Monitorização de desempenho durante a temporada\n• Revisão pós-jogo e feedback', '• Préparation et analyse individuelle des matchs\n• Recrutement adverse et briefings tactiques\n• Suivi des performances en saison\n• Revue et retour d''après-match', '• Individuelle Spielvorbereitung und Analyse\n• Gegnerscouting und taktische Briefings\n• Leistungsmonitoring während der Saison\n• Nachspielanalyse und Feedback', '• Preparazione e analisi individuale delle partite\n• Scouting avversario e briefing tattici\n• Monitoraggio delle prestazioni durante la stagione\n• Revisione e feedback post-partita', '• Indywidualne przygotowanie i analiza meczowa\n• Skauting rywala i odprawy taktyczne\n• Monitoring wydajności w trakcie sezonu\n• Przegląd i feedback po meczu', '• Individuální příprava a analýza zápasů\n• Skautování soupeře a taktické brífinky\n• Monitorování výkonu během sezóny\n• Hodnocení a zpětná vazba po zápase', '• Индивидуальная подготовка и анализ матчей\n• Скаутинг соперника и тактические брифинги\n• Мониторинг результативности в сезоне\n• Послематчевый разбор и обратная связь', '• Bireysel maç hazırlığı ve analizi\n• Rakip keşfi ve taktik brifingleri\n• Sezon içi performans takibi\n• Maç sonrası değerlendirme ve geri bildirim', '• Individualna priprema i analiza utakmica\n• Izviđanje protivnika i taktički brifovi\n• Praćenje performansi tijekom sezone\n• Pregled i povratne informacije nakon utakmice', '• Individuell kampforberedelse og analyse\n• Motstanderspeiding og taktiske briefinger\n• Prestasjonsovervåking i sesongen\n• Kampgjennomgang og tilbakemelding'),
('players', 'progress', 'PROGRESS', 'PROGRESAR', 'PROGREDIR', 'PROGRESSER', 'FORTSCHRITT', 'PROGREDIRE', 'POSTĘP', 'POKROK', 'ПРОГРЕСС', 'İLERLE', 'NAPREDOVATI', 'FREMGANG'),
('players', 'progress_subtitle', 'Advancement & Opportunity', 'Avance y Oportunidad', 'Avanço e Oportunidade', 'Avancement et Opportunité', 'Aufstieg und Chance', 'Avanzamento e Opportunità', 'Awans i Szansa', 'Postup a Příležitost', 'Продвижение и Возможности', 'İlerleme ve Fırsat', 'Napredak i Prilika', 'Fremgang og Mulighet'),
('players', 'progress_desc', 'Your success creates opportunity. As you develop and perform, we leverage our club relationships and market knowledge to secure the right moves at the right time, whether that''s a step up, a new challenge, or securing your legacy at the top level.', 'Tu éxito crea oportunidades. A medida que te desarrollas y rindes, aprovechamos nuestras relaciones con clubes y conocimiento del mercado para asegurar los movimientos correctos en el momento adecuado.', 'O seu sucesso cria oportunidades. À medida que se desenvolve e tem bom desempenho, aproveitamos as nossas relações com clubes e conhecimento do mercado para garantir os movimentos certos no momento certo.', 'Votre succès crée des opportunités. Au fur et à mesure que vous vous développez et performez, nous exploitons nos relations avec les clubs et notre connaissance du marché pour sécuriser les bons mouvements au bon moment.', 'Ihr Erfolg schafft Chancen. Während Sie sich entwickeln und performen, nutzen wir unsere Clubbeziehungen und Marktkenntnisse, um die richtigen Schritte zur richtigen Zeit zu sichern.', 'Il tuo successo crea opportunità. Man mano che ti sviluppi e performi, sfruttiamo le nostre relazioni con i club e la conoscenza del mercato per assicurare le mosse giuste al momento giusto.', 'Twój sukces tworzy możliwości. W miarę jak się rozwijasz i osiągasz wyniki, wykorzystujemy nasze relacje z klubami i wiedzę rynkową, aby zapewnić właściwe ruchy we właściwym czasie.', 'Váš úspěch vytváří příležitosti. Jak se rozvíjíte a podáváte výkony, využíváme naše vztahy s kluby a znalost trhu k zajištění správných kroků ve správný čas.', 'Ваш успех создаёт возможности. По мере вашего развития и выступлений мы используем наши связи с клубами и знание рынка для обеспечения правильных шагов в нужное время.', 'Başarınız fırsat yaratır. Geliştikçe ve performans gösterdikçe, doğru zamanda doğru hamleleri güvence altına almak için kulüp ilişkilerimizi ve pazar bilgimizi kullanıyoruz.', 'Vaš uspjeh stvara prilike. Kako se razvijate i nastupate, koristimo naše odnose s klubovima i poznavanje tržišta kako bismo osigurali prave poteze u pravo vrijeme.', 'Din suksess skaper muligheter. Etter hvert som du utvikler deg og presterer, utnytter vi våre klubbrelasjoner og markedskunnskap for å sikre de riktige trekkene til rett tid.'),
('players', 'progress_details', '• Strategic transfer planning\n• Club relationship management\n• Career milestone optimisation\n• Long-term wealth and legacy planning', '• Planificación estratégica de transferencias\n• Gestión de relaciones con clubes\n• Optimización de hitos profesionales\n• Planificación patrimonial y de legado a largo plazo', '• Planeamento estratégico de transferências\n• Gestão de relações com clubes\n• Otimização de marcos da carreira\n• Planeamento de património e legado a longo prazo', '• Planification stratégique des transferts\n• Gestion des relations avec les clubs\n• Optimisation des jalons de carrière\n• Planification patrimoniale et successorale à long terme', '• Strategische Transferplanung\n• Management von Clubbeziehungen\n• Karrieremeilenstein-Optimierung\n• Langfristige Vermögens- und Nachlassplanung', '• Pianificazione strategica dei trasferimenti\n• Gestione delle relazioni con i club\n• Ottimizzazione delle tappe della carriera\n• Pianificazione patrimoniale e del lascito a lungo termine', '• Strategiczne planowanie transferów\n• Zarządzanie relacjami z klubami\n• Optymalizacja kamieni milowych kariery\n• Długoterminowe planowanie majątku i dziedzictwa', '• Strategické plánování přestupů\n• Řízení vztahů s kluby\n• Optimalizace kariérních milníků\n• Dlouhodobé plánování bohatství a odkazu', '• Стратегическое планирование трансферов\n• Управление отношениями с клубами\n• Оптимизация карьерных вех\n• Долгосрочное планирование благосостояния и наследия', '• Stratejik transfer planlaması\n• Kulüp ilişkileri yönetimi\n• Kariyer dönüm noktası optimizasyonu\n• Uzun vadeli servet ve miras planlaması', '• Strateško planiranje transfera\n• Upravljanje odnosima s klubovima\n• Optimizacija karijernih prekretnica\n• Dugoročno planiranje bogatstva i naslijeđa', '• Strategisk overgangsplanlegging\n• Klubbrelasjonsforvaltning\n• Karrieremilepæloptimalisering\n• Langsiktig formues- og arveplanlegging')
INSERT INTO translations (page_name, text_key, english, spanish, portuguese, french, german, italian, polish, czech, russian, turkish, croatian, norwegian) VALUES
('journey', 'journey.badge', 'The Process', 'El Proceso', 'O Processo', 'Le Processus', 'Der Prozess', 'Il Processo', 'Proces', 'Proces', 'Процесс', 'Süreç', 'Proces', 'Prosessen'),
('journey', 'journey.hero_title_1', 'HOW WE WORK', 'CÓMO TRABAJAMOS', 'COMO TRABALHAMOS', 'COMMENT NOUS TRAVAILLONS', 'WIE WIR ARBEITEN', 'COME LAVORIAMO', 'JAK PRACUJEMY', 'JAK PRACUJEME', 'КАК МЫ РАБОТАЕМ', 'NASIL ÇALIŞIYORUZ', 'KAKO RADIMO', 'HVORDAN VI JOBBER'),
('journey', 'journey.hero_title_2', 'WITH PLAYERS', 'CON JUGADORES', 'COM JOGADORES', 'AVEC LES JOUEURS', 'MIT SPIELERN', 'CON I GIOCATORI', 'Z PIŁKARZAMI', 'S HRÁČI', 'С ИГРОКАМИ', 'OYUNCULARLA', 'S IGRAČIMA', 'MED SPILLERE'),
('journey', 'journey.hero_subtitle', 'From discovery to development: a transparent look at the journey', 'Del descubrimiento al desarrollo: una mirada transparente al camino', 'Da descoberta ao desenvolvimento: uma visão transparente da jornada', 'De la découverte au développement : un regard transparent sur le parcours', 'Von der Entdeckung zur Entwicklung: ein transparenter Blick auf den Weg', 'Dalla scoperta allo sviluppo: uno sguardo trasparente sul percorso', 'Od odkrycia do rozwoju: przejrzysty wgląd w drogę', 'Od objevení k rozvoji: transparentní pohled na cestu', 'От открытия к развитию: прозрачный взгляд на путь', 'Keşiften gelişime: yolculuğa şeffaf bir bakış', 'Od otkrića do razvoja: transparentan pogled na putovanje', 'Fra oppdagelse til utvikling: et transparent blikk på reisen'),
('journey', 'journey.step', 'Step', 'Paso', 'Passo', 'Étape', 'Schritt', 'Passo', 'Krok', 'Krok', 'Шаг', 'Adım', 'Korak', 'Steg'),
('journey', 'journey.step1_title', 'Discovery', 'Descubrimiento', 'Descoberta', 'Découverte', 'Entdeckung', 'Scoperta', 'Odkrycie', 'Objevení', 'Открытие', 'Keşif', 'Otkriće', 'Oppdagelse'),
('journey', 'journey.step1_subtitle', 'How we connect', 'Cómo nos conectamos', 'Como nos conectamos', 'Comment nous nous connectons', 'Wie wir uns verbinden', 'Come ci connettiamo', 'Jak się łączymy', 'Jak se spojíme', 'Как мы связываемся', 'Nasıl bağlanıyoruz', 'Kako se povezujemo', 'Hvordan vi kobles'),
('journey', 'journey.step1_desc', 'The journey begins when we find you, through our extensive European scouting network, or when you reach out to us. Either way, it starts with recognition of talent worth investing in.', 'El viaje comienza cuando te encontramos a través de nuestra extensa red de scouts europea, o cuando tú te pones en contacto con nosotros. De cualquier manera, comienza con el reconocimiento del talento que vale la pena invertir.', 'A jornada começa quando o encontramos, através da nossa extensa rede de scouting europeia, ou quando nos contacta. De qualquer forma, começa com o reconhecimento de talento que vale a pena investir.', 'Le parcours commence quand nous vous trouvons, à travers notre vaste réseau de recrutement européen, ou quand vous nous contactez. Dans tous les cas, cela commence par la reconnaissance d''un talent qui mérite qu''on y investisse.', 'Die Reise beginnt, wenn wir Sie durch unser umfangreiches europäisches Scouting-Netzwerk finden, oder wenn Sie sich an uns wenden. So oder so beginnt es mit der Erkennung eines Talents, in das es sich zu investieren lohnt.', 'Il viaggio inizia quando ti troviamo, attraverso la nostra vasta rete di scouting europea, o quando ci contatti. In entrambi i casi, inizia con il riconoscimento di un talento su cui vale la pena investire.', 'Podróż zaczyna się, gdy cię znajdziemy przez naszą rozległą europejską sieć skautów, lub gdy sam się z nami skontaktujesz. Tak czy inaczej, zaczyna się od rozpoznania talentu wartego inwestycji.', 'Cesta začíná, když vás najdeme prostřednictvím naší rozsáhlé evropské skautingové sítě, nebo když se na nás obrátíte vy. V obou případech to začíná rozpoznáním talentu, do kterého stojí za to investovat.', 'Путь начинается, когда мы находим вас через нашу обширную европейскую скаутинговую сеть, или когда вы обращаетесь к нам. В любом случае, всё начинается с признания таланта, в который стоит инвестировать.', 'Yolculuk, geniş Avrupa keşif ağımız aracılığıyla sizi bulduğumuzda veya siz bize ulaştığınızda başlar. Her iki durumda da yatırım yapmaya değer bir yeteneğin tanınmasıyla başlar.', 'Putovanje počinje kada vas pronađemo, kroz našu opsežnu europsku skautsku mrežu, ili kada se vi obratite nama. U svakom slučaju, počinje prepoznavanjem talenta vrijednog ulaganja.', 'Reisen begynner når vi finner deg, gjennom vårt omfattende europeiske speidernettverk, eller når du tar kontakt med oss. Uansett begynner det med anerkjennelse av talent verdt å investere i.'),
('journey', 'journey.step1_detail1', 'We scout across all of Europe''s professional leagues', 'Exploramos en todas las ligas profesionales de Europa', 'Fazemos scouting em todas as ligas profissionais da Europa', 'Nous recrutons dans toutes les ligues professionnelles d''Europe', 'Wir scouten in allen europäischen Profiligen', 'Effettuiamo scouting in tutti i campionati professionistici europei', 'Skautujemy we wszystkich europejskich ligach zawodowych', 'Skautujeme ve všech evropských profesionálních ligách', 'Мы ведём скаутинг во всех профессиональных лигах Европы', 'Avrupa''nın tüm profesyonel liglerinde keşif yapıyoruz', 'Skautiramo u svim europskim profesionalnim ligama', 'Vi speider på tvers av alle Europas profesjonelle ligaer'),
('journey', 'journey.step1_detail2', 'Players can also request representation directly', 'Los jugadores también pueden solicitar representación directamente', 'Os jogadores também podem solicitar representação diretamente', 'Les joueurs peuvent aussi demander une représentation directement', 'Spieler können auch direkt eine Vertretung beantragen', 'I giocatori possono anche richiedere la rappresentanza direttamente', 'Piłkarze mogą również bezpośrednio poprosić o reprezentację', 'Hráči mohou také přímo požádat o zastoupení', 'Игроки также могут напрямую запросить представительство', 'Oyuncular da doğrudan temsil talep edebilir', 'Igrači također mogu izravno zatražiti zastupanje', 'Spillere kan også be om representasjon direkte'),
('journey', 'journey.step1_detail3', 'Initial assessment of potential and fit', 'Evaluación inicial del potencial y compatibilidad', 'Avaliação inicial do potencial e compatibilidade', 'Évaluation initiale du potentiel et de la compatibilité', 'Erste Bewertung von Potenzial und Passung', 'Valutazione iniziale del potenziale e della compatibilità', 'Wstępna ocena potencjału i dopasowania', 'Počáteční hodnocení potenciálu a shody', 'Первоначальная оценка потенциала и совместимости', 'Potansiyel ve uyum için ilk değerlendirme', 'Početna procjena potencijala i kompatibilnosti', 'Innledende vurdering av potensial og tilpasning'),
('journey', 'journey.step2_title', 'Assessment', 'Evaluación', 'Avaliação', 'Évaluation', 'Bewertung', 'Valutazione', 'Ocena', 'Hodnocení', 'Оценка', 'Değerlendirme', 'Procjena', 'Vurdering'),
('journey', 'journey.step2_subtitle', 'Evaluating the fit', 'Evaluando la compatibilidad', 'Avaliando a compatibilidade', 'Évaluer la compatibilité', 'Die Passung bewerten', 'Valutare la compatibilità', 'Ocena dopasowania', 'Hodnocení shody', 'Оценка совместимости', 'Uyumu değerlendirmek', 'Procjena kompatibilnosti', 'Vurdere tilpasningen'),
('journey', 'journey.step2_desc', 'Not every talented player is right for us, and we might not be right for every player. We take time to assess whether there''s genuine potential for a successful partnership.', 'No todos los jugadores talentosos son adecuados para nosotros, y puede que no seamos adecuados para todos. Nos tomamos el tiempo para evaluar si hay un potencial genuino para una asociación exitosa.', 'Nem todos os jogadores talentosos são certos para nós, e podemos não ser certos para todos os jogadores. Dedicamos tempo para avaliar se há potencial genuíno para uma parceria de sucesso.', 'Tous les joueurs talentueux ne nous conviennent pas, et nous ne convenons peut-être pas à tous les joueurs. Nous prenons le temps d''évaluer s''il existe un véritable potentiel de partenariat réussi.', 'Nicht jeder talentierte Spieler passt zu uns, und wir passen vielleicht nicht zu jedem Spieler. Wir nehmen uns die Zeit zu beurteilen, ob echtes Potenzial für eine erfolgreiche Partnerschaft besteht.', 'Non tutti i giocatori talentuosi sono giusti per noi, e noi potremmo non essere giusti per ogni giocatore. Ci prendiamo il tempo per valutare se c''è un vero potenziale per una partnership di successo.', 'Nie każdy utalentowany piłkarz jest dla nas odpowiedni i my możemy nie być odpowiedni dla każdego. Poświęcamy czas na ocenę, czy istnieje rzeczywisty potencjał na udaną współpracę.', 'Ne každý talentovaný hráč je pro nás ten pravý a my nemusíme být ti praví pro každého hráče. Dáváme si čas na posouzení, zda existuje skutečný potenciál pro úspěšné partnerství.', 'Не каждый талантливый игрок подходит нам, и мы можем не подходить каждому игроку. Мы уделяем время оценке того, есть ли реальный потенциал для успешного партнёрства.', 'Her yetenekli oyuncu bizim için doğru olmayabilir ve biz de her oyuncu için doğru olmayabiliriz. Başarılı bir ortaklık için gerçek bir potansiyel olup olmadığını değerlendirmek için zaman ayırıyoruz.', 'Nije svaki talentirani igrač pravi za nas, i mi možda nismo pravi za svakog igrača. Uzimamo si vremena procijeniti postoji li stvarni potencijal za uspješno partnerstvo.', 'Ikke alle talentfulle spillere passer for oss, og vi passer kanskje ikke for alle spillere. Vi tar oss tid til å vurdere om det er genuint potensial for et vellykket partnerskap.'),
('journey', 'journey.step2_detail1', 'Review of playing style, mentality, and ambition', 'Revisión del estilo de juego, mentalidad y ambición', 'Revisão do estilo de jogo, mentalidade e ambição', 'Examen du style de jeu, de la mentalité et de l''ambition', 'Überprüfung von Spielstil, Mentalität und Ehrgeiz', 'Revisione dello stile di gioco, mentalità e ambizione', 'Przegląd stylu gry, mentalności i ambicji', 'Přezkoumání herního stylu, mentality a ambicí', 'Обзор стиля игры, менталитета и амбиций', 'Oyun stili, mentalite ve hırs incelemesi', 'Pregled stila igre, mentaliteta i ambicije', 'Gjennomgang av spillestil, mentalitet og ambisjoner'),
('journey', 'journey.step2_detail2', 'Understanding your goals and timeline', 'Comprender tus objetivos y plazos', 'Compreender os seus objetivos e cronograma', 'Comprendre vos objectifs et votre calendrier', 'Verstehen Ihrer Ziele und Ihres Zeitplans', 'Comprendere i tuoi obiettivi e la tua timeline', 'Zrozumienie twoich celów i harmonogramu', 'Porozumění vašim cílům a časovému plánu', 'Понимание ваших целей и сроков', 'Hedeflerinizi ve zaman çizelgenizi anlama', 'Razumijevanje vaših ciljeva i vremenskog okvira', 'Forstå dine mål og tidsplan'),
('journey', 'journey.step2_detail3', 'Honest assessment of where you are and where you could be', 'Evaluación honesta de dónde estás y dónde podrías estar', 'Avaliação honesta de onde está e onde poderia estar', 'Évaluation honnête de là où vous en êtes et où vous pourriez être', 'Ehrliche Einschätzung, wo Sie stehen und wo Sie sein könnten', 'Valutazione onesta di dove sei e dove potresti essere', 'Szczera ocena tego, gdzie jesteś i gdzie mógłbyś być', 'Upřímné zhodnocení toho, kde jste a kde byste mohli být', 'Честная оценка того, где вы находитесь и где могли бы быть', 'Nerede olduğunuzun ve nerede olabileceğinizin dürüst değerlendirmesi', 'Iskrena procjena gdje ste i gdje biste mogli biti', 'Ærlig vurdering av hvor du er og hvor du kan være'),
('journey', 'journey.step3_title', 'Discussion', 'Discusión', 'Discussão', 'Discussion', 'Gespräch', 'Discussione', 'Rozmowa', 'Diskuse', 'Обсуждение', 'Görüşme', 'Razgovor', 'Diskusjon'),
('journey', 'journey.step3_subtitle', 'Full transparency', 'Total transparencia', 'Total transparência', 'Transparence totale', 'Volle Transparenz', 'Piena trasparenza', 'Pełna przejrzystość', 'Plná transparentnost', 'Полная прозрачность', 'Tam şeffaflık', 'Potpuna transparentnost', 'Full åpenhet'),
('journey', 'journey.step3_desc', 'We have detailed conversations about what we offer, what we expect, and what the journey looks like. For under-18s, parents are fully involved in every discussion.', 'Tenemos conversaciones detalladas sobre lo que ofrecemos, lo que esperamos y cómo es el camino. Para menores de 18 años, los padres participan plenamente en cada discusión.', 'Temos conversas detalhadas sobre o que oferecemos, o que esperamos e como é a jornada. Para menores de 18 anos, os pais estão totalmente envolvidos em todas as discussões.', 'Nous avons des conversations détaillées sur ce que nous offrons, ce que nous attendons et à quoi ressemble le parcours. Pour les moins de 18 ans, les parents sont pleinement impliqués dans chaque discussion.', 'Wir führen detaillierte Gespräche darüber, was wir bieten, was wir erwarten und wie der Weg aussieht. Für Unter-18-Jährige sind die Eltern vollständig in jedes Gespräch einbezogen.', 'Abbiamo conversazioni dettagliate su ciò che offriamo, cosa ci aspettiamo e come si presenta il percorso. Per i minori di 18 anni, i genitori sono pienamente coinvolti in ogni discussione.', 'Prowadzimy szczegółowe rozmowy o tym, co oferujemy, czego oczekujemy i jak wygląda droga. W przypadku osób poniżej 18 roku życia rodzice są w pełni zaangażowani w każdą dyskusję.', 'Vedeme podrobné rozhovory o tom, co nabízíme, co očekáváme a jak cesta vypadá. Pro hráče do 18 let jsou rodiče plně zapojeni do každé diskuse.', 'Мы ведём подробные беседы о том, что мы предлагаем, чего ожидаем и как выглядит путь. Для несовершеннолетних родители полностью вовлечены в каждое обсуждение.', 'Ne sunduğumuz, ne beklediğimiz ve yolculuğun nasıl göründüğü hakkında ayrıntılı görüşmeler yapıyoruz. 18 yaş altı için aileler her görüşmeye tamamen dahil edilir.', 'Vodimo detaljne razgovore o tome što nudimo, što očekujemo i kako putovanje izgleda. Za mlađe od 18 godina, roditelji su potpuno uključeni u svaku raspravu.', 'Vi har detaljerte samtaler om hva vi tilbyr, hva vi forventer, og hvordan reisen ser ut. For under 18 år er foreldre fullt involvert i enhver diskusjon.'),
('journey', 'journey.step3_detail1', 'Clear explanation of our services and approach', 'Explicación clara de nuestros servicios y enfoque', 'Explicação clara dos nossos serviços e abordagem', 'Explication claire de nos services et de notre approche', 'Klare Erklärung unserer Dienstleistungen und unseres Ansatzes', 'Spiegazione chiara dei nostri servizi e del nostro approccio', 'Jasne wyjaśnienie naszych usług i podejścia', 'Jasné vysvětlení našich služeb a přístupu', 'Четкое объяснение наших услуг и подхода', 'Hizmetlerimizin ve yaklaşımımızın açık açıklaması', 'Jasno objašnjenje naših usluga i pristupa', 'Tydelig forklaring av våre tjenester og tilnærming'),
('journey', 'journey.step3_detail2', 'Discussion of development pathway', 'Discusión de la vía de desarrollo', 'Discussão do percurso de desenvolvimento', 'Discussion du parcours de développement', 'Diskussion des Entwicklungswegs', 'Discussione del percorso di sviluppo', 'Omówienie ścieżki rozwoju', 'Diskuse o rozvojové cestě', 'Обсуждение пути развития', 'Gelişim yolu tartışması', 'Rasprava o razvojnom putu', 'Diskusjon av utviklingsvei'),
('journey', 'journey.step3_detail3', 'Parent/guardian involvement for youth players', 'Participación de padres/tutores para jugadores jóvenes', 'Envolvimento dos pais/tutores para jogadores jovens', 'Implication des parents/tuteurs pour les jeunes joueurs', 'Eltern-/Erziehungsberechtigtenbeteiligung für Jugendspieler', 'Coinvolgimento dei genitori/tutori per i giovani giocatori', 'Zaangażowanie rodziców/opiekunów dla młodych piłkarzy', 'Zapojení rodičů/opatrovníků pro mladé hráče', 'Участие родителей/опекунов для молодых игроков', 'Genç oyuncular için ebeveyn/veli katılımı', 'Uključenost roditelja/skrbnika za mlade igrače', 'Foreldre-/foresatteinvolvering for unge spillere'),
('journey', 'journey.step3_detail4', 'No pressure. Take the time you need', 'Sin presión. Tómate el tiempo que necesites', 'Sem pressão. Tome o tempo que precisar', 'Pas de pression. Prenez le temps qu''il vous faut', 'Kein Druck. Nehmen Sie sich die Zeit, die Sie brauchen', 'Nessuna pressione. Prendi il tempo che ti serve', 'Bez presji. Poświęć tyle czasu, ile potrzebujesz', 'Žádný nátlak. Vezměte si čas, který potřebujete', 'Никакого давления. Не торопитесь', 'Baskı yok. İhtiyacınız olan zamanı ayırın', 'Bez pritiska. Uzmite koliko vremena trebate', 'Ingen press. Ta den tiden du trenger'),
('journey', 'journey.step4_title', 'Agreement', 'Acuerdo', 'Acordo', 'Accord', 'Vereinbarung', 'Accordo', 'Umowa', 'Dohoda', 'Соглашение', 'Anlaşma', 'Dogovor', 'Avtale'),
('journey', 'journey.step4_subtitle', 'Formalising the partnership', 'Formalizando la asociación', 'Formalizando a parceria', 'Formaliser le partenariat', 'Die Partnerschaft formalisieren', 'Formalizzare la partnership', 'Formalizacja partnerstwa', 'Formalizace partnerství', 'Оформление партнёрства', 'Ortaklığı resmileştirmek', 'Formaliziranje partnerstva', 'Formalisering av partnerskapet'),
('journey', 'journey.step4_desc', 'Once we''re aligned on goals and approach, we formalise the partnership. Everything is clear, documented, and agreed upon by all parties.', 'Una vez que estamos alineados en objetivos y enfoque, formalizamos la asociación. Todo es claro, documentado y acordado por todas las partes.', 'Uma vez alinhados nos objetivos e abordagem, formalizamos a parceria. Tudo é claro, documentado e acordado por todas as partes.', 'Une fois que nous sommes alignés sur les objectifs et l''approche, nous formalisons le partenariat. Tout est clair, documenté et convenu par toutes les parties.', 'Sobald wir uns bei Zielen und Ansatz einig sind, formalisieren wir die Partnerschaft. Alles ist klar, dokumentiert und von allen Parteien vereinbart.', 'Una volta allineati su obiettivi e approccio, formalizziamo la partnership. Tutto è chiaro, documentato e concordato da tutte le parti.', 'Gdy uzgodnimy cele i podejście, formalizujemy partnerstwo. Wszystko jest jasne, udokumentowane i uzgodnione przez wszystkie strony.', 'Jakmile se shodneme na cílech a přístupu, formalizujeme partnerství. Vše je jasné, zdokumentované a odsouhlasené všemi stranami.', 'Когда мы согласованы в целях и подходе, мы оформляем партнёрство. Всё ясно, задокументировано и согласовано всеми сторонами.', 'Hedefler ve yaklaşım konusunda uyum sağladığımızda ortaklığı resmileştiriyoruz. Her şey açık, belgelenmiş ve tüm taraflarca kabul edilmiş.', 'Kada se uskladimo oko ciljeva i pristupa, formaliziramo partnerstvo. Sve je jasno, dokumentirano i dogovoreno od svih strana.', 'Når vi er samkjørte om mål og tilnærming, formaliserer vi partnerskapet. Alt er tydelig, dokumentert og avtalt av alle parter.'),
('journey', 'journey.step4_detail1', 'Transparent fee structure explained', 'Estructura de tarifas transparente explicada', 'Estrutura de taxas transparente explicada', 'Structure tarifaire transparente expliquée', 'Transparente Gebührenstruktur erklärt', 'Struttura tariffaria trasparente spiegata', 'Przejrzysta struktura opłat wyjaśniona', 'Transparentní struktura poplatků vysvětlena', 'Прозрачная структура оплаты объяснена', 'Şeffaf ücret yapısı açıklandı', 'Transparentna struktura naknada objašnjena', 'Transparent gebyrstruktur forklart'),
('journey', 'journey.step4_detail2', 'Clear terms and expectations', 'Términos y expectativas claros', 'Termos e expectativas claros', 'Termes et attentes clairs', 'Klare Bedingungen und Erwartungen', 'Termini e aspettative chiari', 'Jasne warunki i oczekiwania', 'Jasné podmínky a očekávání', 'Четкие условия и ожидания', 'Açık şartlar ve beklentiler', 'Jasni uvjeti i očekivanja', 'Klare vilkår og forventninger'),
('journey', 'journey.step4_detail3', 'Family involvement and approval where relevant', 'Participación y aprobación familiar cuando sea relevante', 'Envolvimento e aprovação familiar quando relevante', 'Implication et approbation de la famille lorsque c''est pertinent', 'Familienbeteiligung und -genehmigung, wo relevant', 'Coinvolgimento e approvazione della famiglia dove pertinente', 'Zaangażowanie i zgoda rodziny, gdy jest to istotne', 'Zapojení a souhlas rodiny, kde je to relevantní', 'Участие и одобрение семьи, где это уместно', 'İlgili durumlarda aile katılımı ve onayı', 'Uključenost i odobrenje obitelji gdje je relevantno', 'Familieinvolvering og godkjenning der det er relevant'),
('journey', 'journey.step5_title', 'Development', 'Desarrollo', 'Desenvolvimento', 'Développement', 'Entwicklung', 'Sviluppo', 'Rozwój', 'Rozvoj', 'Развитие', 'Gelişim', 'Razvoj', 'Utvikling'),
('journey', 'journey.step5_subtitle', 'The work begins', 'El trabajo comienza', 'O trabalho começa', 'Le travail commence', 'Die Arbeit beginnt', 'Il lavoro inizia', 'Praca się zaczyna', 'Práce začíná', 'Работа начинается', 'İş başlıyor', 'Posao počinje', 'Arbeidet begynner'),
('journey', 'journey.step5_desc', 'This is where the real journey starts. You get access to our performance teams, match analysis, development programmes, and the full weight of our network and expertise.', 'Aquí es donde comienza el verdadero viaje. Obtienes acceso a nuestros equipos de rendimiento, análisis de partidos, programas de desarrollo y todo el peso de nuestra red y experiencia.', 'É aqui que a verdadeira jornada começa. Obtém acesso às nossas equipas de desempenho, análise de jogos, programas de desenvolvimento e toda a força da nossa rede e experiência.', 'C''est ici que le vrai parcours commence. Vous accédez à nos équipes de performance, à l''analyse des matchs, aux programmes de développement et à toute la force de notre réseau et de notre expertise.', 'Hier beginnt die eigentliche Reise. Sie erhalten Zugang zu unseren Performance-Teams, Spielanalysen, Entwicklungsprogrammen und der vollen Stärke unseres Netzwerks und unserer Expertise.', 'È qui che inizia il vero viaggio. Ottieni accesso ai nostri team di performance, analisi delle partite, programmi di sviluppo e tutta la forza della nostra rete e competenza.', 'To jest miejsce, gdzie prawdziwa podróż się zaczyna. Uzyskujesz dostęp do naszych zespołów wydajnościowych, analizy meczowej, programów rozwojowych i pełnej siły naszej sieci i wiedzy.', 'Tady začíná skutečná cesta. Získáte přístup k našim výkonnostním týmům, analýze zápasů, rozvojovým programům a plné síle naší sítě a odborných znalostí.', 'Именно здесь начинается настоящий путь. Вы получаете доступ к нашим командам по эффективности, анализу матчей, программам развития и всей мощи нашей сети и экспертизы.', 'Gerçek yolculuk burada başlıyor. Performans ekiplerimize, maç analizine, gelişim programlarına ve ağımızın ve uzmanlığımızın tüm gücüne erişim elde ediyorsunuz.', 'Ovdje počinje pravo putovanje. Dobivate pristup našim timovima za performanse, analizu utakmica, razvojnim programima i punoj snazi naše mreže i stručnosti.', 'Det er her den virkelige reisen begynner. Du får tilgang til våre prestasjonsteam, kampanalyse, utviklingsprogrammer og den fulle tyngden av vårt nettverk og ekspertise.'),
